/**
 * Purges every deleted workspace whose retention window has closed at `now`.
 * One workspace failing is counted and logged, never allowed to stop the rest.
 */
async function purgeExpiredWorkspaces(
  now: Date,
  result: JobResult,
): Promise<void> {
  for (const org of await orgRepo.listDeletedOrgs()) {
    if (org.archivedAt === null) continue;
    if (!hasElapsedDays(org.archivedAt, DELETED_WORKSPACE_RETENTION_DAYS, now)) {
      continue;
    }

    try {
      if (await orgRepo.purgeOrg(org.id)) {
        forgetOrgRateLimits(org.id);
        result.processed += 1;
        logger.info("deleted workspace purged", { orgId: org.id });
      }
    } catch (error) {
      result.failed += 1;
      logger.error("workspace purge failed", {
        orgId: org.id,
        reason: error instanceof Error ? error.message : String(error),
