/**
 * Deleting a workspace is a grace period followed by a purge: for
 * `DELETED_WORKSPACE_RETENTION_DAYS` it is kept inert and its owner can restore
 * it; afterwards the retention sweep removes every trace of it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityFilterSchema } from "@/schemas/activity";
import { getDb } from "@/server/db";
import { sessions } from "@/server/db/schema/users";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  listOrganizationsForUser,
  restoreOrganization,
} from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { resolveActorForOrg } from "@/server/services/session-service";
import { hashToken } from "@/lib/hash";
import * as issueService from "@/server/services/issue-service";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * DAY_MS;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function deleteTenant(tenant: Tenant) {
  return deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** Tables that carry an `org_id` column, straight from SQLite. */
function tenantTables(): string[] {
  const client = getDb().$client;
  const tables = client
    .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
    .all() as { name: string }[];
  return tables
    .map((table) => table.name)
    .filter((name) =>
      (client.prepare(`PRAGMA table_info("${name}")`).all() as { name: string }[]).some(
        (column) => column.name === "org_id",
      ),
    );
}

/** One row per tenant table, so a purge that forgets a table shows up. */
function populateEveryTenantTable(orgId: OrgId): void {
  const client = getDb().$client;
  for (const table of tenantTables()) {
    const columns = client.prepare(`PRAGMA table_info("${table}")`).all() as {
      name: string;
      type: string;
      notnull: number;
      dflt_value: string | null;
    }[];
    const wanted = columns.filter(
      (column) => column.name === "org_id" || (column.notnull === 1 && column.dflt_value === null),
    );
    const values = wanted.map((column) =>
      column.name === "org_id"
        ? orgId
        : column.type.toUpperCase() === "INTEGER"
          ? 1
          : `${table}.${column.name}.${orgId}`,
    );
    client
      .prepare(
        `INSERT INTO "${table}" (${wanted.map((c) => `"${c.name}"`).join(", ")}) VALUES (${wanted
          .map(() => "?")
          .join(", ")})`,
      )
      .run(...values);
  }
}

function rowsFor(orgId: OrgId): Record<string, number> {
  const client = getDb().$client;
  return Object.fromEntries(
    tenantTables().map((table) => [
      table,
      (client.prepare(`SELECT count(*) AS n FROM "${table}" WHERE org_id = ?`).get(orgId) as { n: number }).n,
    ]),
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("deleting", () => {
  it("publishes organization.deleted and audits it", async () => {
    const tenant = await createTenant("delevent");
    const off = registerActivityListeners();
    detachers.push(off);
    const seen = capture("organization.deleted");

    await deleteTenant(tenant);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: tenant.org.slug,
    });

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit).toHaveLength(1);
    expect(audit[0]).toMatchObject({
      action: "organization.deleted",
      actorId: tenant.userIds.owner,
    });
  });

  it("audits even when the audit listeners are not attached", async () => {
    const tenant = await createTenant("delaudit");
    await deleteTenant(tenant);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action)).toEqual(["organization.deleted"]);
  });

  it("records an event published by something else, once per emit", async () => {
    const tenant = await createTenant("delforeign");
    detachers.push(registerActivityListeners());

    const { emit } = await import("@/lib/event-bus");
    await emit("organization.restored", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: tenant.org.createdAt,
      slug: tenant.org.slug,
    });

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action)).toEqual(["organization.restored"]);
  });

  it("accepts the new actions in the audit-log filter schema", () => {
    const parsed = activityFilterSchema.safeParse({
      orgId: "01HZZZGGGGGGGGGGGGGGGGGGGG",
      action: ["organization.deleted", "organization.restored"],
      limit: 25,
      cursor: null,
    });
    expect(parsed.success).toBe(true);
  });

  it("refuses to delete a workspace that is already deleted", async () => {
    const tenant = await createTenant("deltwice");
    await deleteTenant(tenant);

    await expect(deleteTenant(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("still requires the typed confirmation", async () => {
    const tenant = await createTenant("delconfirm");
    await expect(
      deleteOrganization(tenant.actors.owner, { orgId: tenant.org.id, confirmSlug: "nope" }),
    ).rejects.toThrow(/confirmation/);
    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).toBeNull();
  });
});

describe("while deleted", () => {
  it("cannot be signed in to, is not listed, and keeps its slug reserved", async () => {
    const tenant = await createTenant("inert");
    const principal = {
      userId: tenant.userIds.member,
      email: "member@inert.test",
      activeOrgId: null,
      expiresAt: toIsoTimestamp(new Date(Date.now() + DAY_MS)),
    };

    await expect(resolveActorForOrg(principal, "inert")).resolves.not.toBeNull();
    await expect(listOrganizationsForUser(tenant.userIds.member)).resolves.toHaveLength(1);

    await deleteTenant(tenant);

    await expect(resolveActorForOrg(principal, "inert")).resolves.toBeNull();
    await expect(listOrganizationsForUser(tenant.userIds.member)).resolves.toHaveLength(0);

    const other = await userRepo.insertUser({
      email: "someone@inert-else.test",
      name: "Someone",
      passwordHash: "seed",
    });
    const created = await createOrganization(other.id, {
      name: "Inert again",
      slug: "inert",
      plan: "free",
    });
    expect(created.slug).not.toBe("inert");
  });

  it("creates no notifications", async () => {
    const tenant = await createTenant("quiet");
    await deleteTenant(tenant);

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
      title: "t",
      body: "b",
      href: "/x",
      actorId: tenant.userIds.admin,
    });
    expect(rows).toEqual([]);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const after = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
      title: "t",
      body: "b",
      href: "/x",
      actorId: tenant.userIds.admin,
    });
    expect(after).toHaveLength(1);
  });

  it("cannot have an invitation accepted, and the invitation stays pending", async () => {
    const tenant = await createTenant("invited");
    const invitee = await userRepo.insertUser({
      email: "invitee@invited.test",
      name: "Invitee",
      passwordHash: "seed",
    });
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "invitee@invited.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken("tok-invited"),
    );

    await deleteTenant(tenant);

    await expect(acceptInvitation(invitee.id, { token: "tok-invited" })).rejects.toBeInstanceOf(
      NotFoundError,
    );
    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toEqual([invitation.id]);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const member = await acceptInvitation(invitee.id, { token: "tok-invited" });
    expect(member.orgId).toBe(tenant.org.id);
  });
});

describe("background jobs", () => {
  const NOW = new Date("2026-06-01T07:00:00.000Z");

  it("skip a deleted workspace and resume after a restore", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("jobsinert");
    await usageRepo.recomputeUsage(tenant.org.id);
    const before = await usageRepo.getUsage(tenant.org.id);

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );
    await deleteTenant(tenant);

    const overdue = capture("issue.overdue");
    expect((await runOverdueIssueJob(NOW)).processed).toBe(0);
    expect(overdue).toHaveLength(0);

    await runUsageRollupJob(NOW);
    expect(await usageRepo.getUsage(tenant.org.id)).toEqual(before);
    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(tenant.org.id);

    await runDigestEmailJob(NOW);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(await usageRepo.listOrgIdsForRollup(100)).toContain(tenant.org.id);
    expect((await runOverdueIssueJob(NOW)).processed).toBe(1);
    expect(overdue).toHaveLength(1);
  });

  it("does not downgrade an ended trial", async () => {
    const tenant = await createTenant("trialinert", "growth");
    const client = getDb().$client;
    client
      .prepare(
        "UPDATE subscriptions SET status = 'trialing', current_period_end = ? WHERE org_id = ?",
      )
      .run("2026-05-01T00:00:00.000Z", tenant.org.id);
    await deleteTenant(tenant);

    const changed = capture("billing.plan_changed");
    await runTrialExpiryJob(NOW);
    expect(changed).toHaveLength(0);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await runTrialExpiryJob(NOW);
    expect(changed).toHaveLength(1);
  });

  it("mark pending webhook deliveries failed rather than delivered", async () => {
    const tenant = await createTenant("hookinert", "growth");
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.com/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );
    await deleteTenant(tenant);

    await runWebhookDeliveryJob(NOW);

    const row = getDb()
      .$client.prepare("SELECT status FROM webhook_deliveries WHERE id = ?")
      .get(delivery.id) as { status: string };
    expect(row.status).toBe("failed");
  });
});

describe("restoring", () => {
  it("brings the workspace back and publishes organization.restored", async () => {
    const tenant = await createTenant("restore");
    await deleteTenant(tenant);
    const seen = capture("organization.restored");

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(restored.archivedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: tenant.org.slug,
    });

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action).sort()).toEqual([
      "organization.deleted",
      "organization.restored",
    ]);

    await expect(listOrganizationsForUser(tenant.userIds.owner)).resolves.toHaveLength(1);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await createTenant("restorelive");
    const seen = capture("organization.restored");

    const same = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(same).toEqual(tenant.org);
    expect(seen).toHaveLength(0);
  });

  it("is a NotFoundError for an unknown workspace and for a stranger", async () => {
    const tenant = await createTenant("restorenf");
    const other = await createTenant("restorenf2");
    await deleteTenant(tenant);

    await expect(
      restoreOrganization(tenant.userIds.owner, "01HZZZGGGGGGGGGGGGGGGGGGGG" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(other.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("is a PermissionDeniedError for a member who is not an owner", async () => {
    const tenant = await createTenant("restoreperm");
    await deleteTenant(tenant);

    for (const role of ["admin", "member", "viewer"] as const) {
      await expect(
        restoreOrganization(tenant.userIds[role], tenant.org.id),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }
    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).not.toBeNull();
  });

  it("is a NotFoundError once the window has closed, purged or not", async () => {
    const tenant = await createTenant("restorelate");
    const deleted = await deleteTenant(tenant);
    const deletedAt = Date.parse(deleted.archivedAt as string);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(deletedAt + WINDOW_MS - 1);
    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();

    await orgRepo.archiveOrg(tenant.org.id);
    const again = (await orgRepo.findOrgById(tenant.org.id))?.archivedAt as string;
    vi.setSystemTime(Date.parse(again) + WINDOW_MS);
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("the retention sweep", () => {
  it("purges a workspace exactly when its window closes, and nothing else", async () => {
    const doomed = await createTenant("purgeme");
    const fresh = await createTenant("purgefresh");
    const live = await createTenant("purgelive");
    for (const tenant of [doomed, fresh, live]) {
      await usageRepo.recomputeUsage(tenant.org.id);
      populateEveryTenantTable(tenant.org.id);
    }

    const session = await sessionRepo.createSession(
      doomed.userIds.owner,
      "hash-purge",
      toIsoTimestamp(new Date(Date.now() + DAY_MS)),
    );
    getDb()
      .update(sessions)
      .set({ activeOrgId: doomed.org.id })
      .where(sessions.tokenHash.name ? undefined : undefined)
      .run();
    expect(session.userId).toBe(doomed.userIds.owner);

    const doomedDeleted = await deleteTenant(doomed);
    await deleteTenant(fresh);
    const deletedAt = Date.parse(doomedDeleted.archivedAt as string);

    const early = await runCleanupArchivedJob(new Date(deletedAt + WINDOW_MS - 1));
    expect(early.failed).toBe(0);
    expect(await orgRepo.findOrgById(doomed.org.id)).not.toBeNull();

    const result = await runCleanupArchivedJob(new Date(deletedAt + WINDOW_MS + 1_000));
    expect(result.failed).toBe(0);
    expect(result.processed).toBeGreaterThanOrEqual(1);

    expect(await orgRepo.findOrgById(doomed.org.id)).toBeNull();
    expect(Object.values(rowsFor(doomed.org.id)).every((n) => n === 0)).toBe(true);

    // The workspace that was deleted later, and the live one, are untouched.
    expect(await orgRepo.findOrgById(fresh.org.id)).not.toBeNull();
    expect(Object.values(rowsFor(fresh.org.id)).every((n) => n > 0)).toBe(true);
    expect(Object.values(rowsFor(live.org.id)).every((n) => n > 0)).toBe(true);
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();

    // Users stay; the pinned session has no active workspace any more.
    expect(await userRepo.findUserById(doomed.userIds.owner)).not.toBeNull();
    const pinned = getDb().$client
      .prepare("SELECT active_org_id AS a FROM sessions WHERE token_hash = ?")
      .get("hash-purge") as { a: string | null };
    expect(pinned.a).toBeNull();

    await expect(
      restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(doomed.org.id);

    const reborn = await createOrganization(doomed.userIds.owner, {
      name: "Purgeme again",
      slug: "purgeme",
      plan: "free",
    });
    expect(reborn.slug).toBe("purgeme");
  });

  it("never purges a live workspace, however old", async () => {
    const tenant = await createTenant("purgeold");
    await usageRepo.recomputeUsage(tenant.org.id);

    await runCleanupArchivedJob(new Date(Date.now() + 10 * WINDOW_MS));

    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
    expect(await orgRepo.purgeOrg(tenant.org.id)).toBe(false);
  });
});

